const sumCreditSettled = `-- name: SumCreditSettled :one
SELECT CAST(COALESCE(SUM(amount), 0) AS SIGNED) AS total
FROM purchase_return_settlements
WHERE return_id = ? AND settlement_type IN ('supplier_credit', 'customer_credit')
`

// Value of the return already kept as supplier balance (N-40): payments must
// not refund or offset it a second time. Old rows may carry the sales name.
func (q *Queries) SumCreditSettled(ctx context.Context, returnID int64) (int64, error) {
	row := q.db.QueryRowContext(ctx, sumCreditSettled, returnID)
	var total int64
	err := row.Scan(&total)
	return total, err
}

const sumCreditSettledByReturns = `-- name: SumCreditSettledByReturns :many
SELECT return_id, CAST(COALESCE(SUM(amount), 0) AS SIGNED) AS total
FROM purchase_return_settlements
WHERE return_id IN (/*SLICE:return_ids*/?) AND settlement_type IN ('supplier_credit', 'customer_credit')
GROUP BY return_id
`

type SumCreditSettledByReturnsRow struct {
	ReturnID int64
	Total    int64
}

// Credit settled per return for a page of returns (saldo list, N-41). Old rows
// may carry the sales name 'customer_credit'.
func (q *Queries) SumCreditSettledByReturns(ctx context.Context, returnIds []int64) ([]SumCreditSettledByReturnsRow, error) {
	query := sumCreditSettledByReturns
	var queryParams []interface{}
	if len(returnIds) > 0 {
		for _, v := range returnIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:return_ids*/?", strings.Repeat(",?", len(returnIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:return_ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SumCreditSettledByReturnsRow{}
	for rows.Next() {
		var i SumCreditSettledByReturnsRow
		if err := rows.Scan(&i.ReturnID, &i.Total); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const transitionReturn = `-- name: TransitionReturn :execresult
UPDATE purchase_returns
SET status = ?, updated_at = ?, updated_by = ?
WHERE id = ? AND status IN (/*SLICE:from_statuses*/?)
`

type TransitionReturnParams struct {
	ToStatus     string
	Now          time.Time
	ActorID      sql.NullInt64
	ID           int64
	FromStatuses []string
}

// CAS: moves the status only from one of the allowed origins.
func (q *Queries) TransitionReturn(ctx context.Context, arg TransitionReturnParams) (sql.Result, error) {
	query := transitionReturn
	var queryParams []interface{}
	queryParams = append(queryParams, arg.ToStatus)
	queryParams = append(queryParams, arg.Now)
	queryParams = append(queryParams, arg.ActorID)
	queryParams = append(queryParams, arg.ID)
	if len(arg.FromStatuses) > 0 {
		for _, v := range arg.FromStatuses {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:from_statuses*/?", strings.Repeat(",?", len(arg.FromStatuses))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:from_statuses*/?", "NULL", 1)
	}
	return q.db.ExecContext(ctx, query, queryParams...)
}
